+/* Count the callbacks actually registered on a chain. chain_items_max is a
+ * high-water mark that never shrinks, so it overstates after an unwrap. */
+static int32_t chain_live_items(const hook_chain_t *chain)
+{
+    int32_t live = 0;
+    for (int32_t i = 0; i < HOOK_CHAIN_NUM; i++) {
+        if (chain->states[i] == CHAIN_ITEM_STATE_READY) live++;
+    }
+    return live;
+}
+
+static int32_t fp_chain_live_items(const fp_hook_chain_t *chain)
+{
+    int32_t live = 0;
+    for (int32_t i = 0; i < FP_HOOK_CHAIN_NUM; i++) {
+        if (chain->states[i] == CHAIN_ITEM_STATE_READY) live++;
+    }
+    return live;
+}
