+int kp_hook_snapshot(kp_hook_info_t *out, int max)
+{
+    int total = 0;
+
+    if (!out || max <= 0) return 0;
+
+    for (uint64_t addr = mem_region_start; addr < mem_region_end; addr += sizeof(hook_mem_warp_t)) {
+        hook_mem_warp_t *wrap = (hook_mem_warp_t *)addr;
+
+        if (!wrap->using) continue;
+        total++;
+        if (total > max) continue;
+
+        kp_hook_info_t *info = &out[total - 1];
+        info->origin_addr = wrap->addr;
+        info->type = wrap->type;
+        info->items = 0;
+        info->replace_addr = 0;
+
+        switch (wrap->type) {
+        case INLINE:
+            info->replace_addr = wrap->chain.inl.replace_addr;
+            break;
+        case INLINE_CHAIN:
+            info->replace_addr = wrap->chain.inl_chain.hook.replace_addr;
+            info->items = chain_live_items(&wrap->chain.inl_chain);
+            break;
+        case FUNCTION_POINTER_CHAIN:
+            info->replace_addr = wrap->chain.fp_chain.hook.fp_addr;
+            info->items = fp_chain_live_items(&wrap->chain.fp_chain);
+            break;
+        default:
+            break;
+        }
+    }
+
+    return total;
+}

