+/*
+ * Nearest-symbol lookup: the hook list knows only addresses, and an address
+ * on its own tells a user nothing.
+ *
+ * kallsyms is address ordered, so the answer is the last symbol at or below
+ * the target. The whole table is walked rather than stopping at the first
+ * symbol past the target, because loadable-module symbols are interleaved
+ * with kernel ones instead of sorted with them.
+ */
+struct kp_addr_symbol
+{
+    unsigned long target;
+    unsigned long best;
+    const char *name;
+};
+
+static int kp_addr_symbol_cb(void *data, const char *name, struct module *module, unsigned long addr)
+{
+    struct kp_addr_symbol *ctx = data;
+    (void)module;
+    if (addr && addr <= ctx->target && addr >= ctx->best) {
+        ctx->best = addr;
+        ctx->name = name;
+    }
+    return 0;
+}
+
+static int kp_addr_symbol_cb_nomod(void *data, const char *name, unsigned long addr)
+{
+    return kp_addr_symbol_cb(data, name, 0, addr);
+}
+
+typedef int (*kallsyms_each_nomod_t)(int (*fn)(void *, const char *, unsigned long), void *data);
+
+int symbol_name_for_addr(unsigned long addr, char *out, int size)
+{
+    struct kp_addr_symbol ctx;
+    int i;
+
+    if (!out || size <= 0) return -EINVAL;
+    out[0] = '\0';
+    if (!kallsyms_on_each_symbol || !addr) return -ENOENT;
+
+    ctx.target = addr;
+    ctx.best = 0;
+    ctx.name = 0;
+
+    if (kver <= VERSION(6, 1, 0)) {
+        kallsyms_on_each_symbol(kp_addr_symbol_cb, &ctx);
+    } else {
+        kallsyms_each_nomod_t each = (kallsyms_each_nomod_t)kallsyms_on_each_symbol;
+        each(kp_addr_symbol_cb_nomod, &ctx);
+    }
+
+    if (!ctx.name) return -ENOENT;
+    for (i = 0; i < size - 1 && ctx.name[i]; i++) out[i] = ctx.name[i];
+    out[i] = '\0';
+    return 0;
+}
+KP_EXPORT_SYMBOL(symbol_name_for_addr);
