+/*
+ * Text, not a struct: the two sides of this bridge are built from separate
+ * headers and released independently, so a packed layout would couple them.
+ *
+ *   HOOK_LIST_V1 total=<in use> shown=<lines below>
+ *   type=<name> items=<n> origin=0x<addr> replace=0x<addr> name=<symbol>
+ *
+ * Names are best effort: the nearest symbol at or below the address, which
+ * can be a different function when the compiler split one up.
+ */
+static long hook_snapshot_text(char *out, long capacity)
+{
+    kp_hook_info_t info[KP_HOOK_LIST_MAX];
+    int total, shown;
+    long used;
+    int len;
+
+    total = kp_hook_snapshot(info, KP_HOOK_LIST_MAX);
+    shown = total > KP_HOOK_LIST_MAX ? KP_HOOK_LIST_MAX : total;
+
+    len = snprintf(out, capacity, "HOOK_LIST_V1 total=%d shown=%d", total, shown);
+    if (len < 0) return -EINVAL;
+    if (len >= capacity) return -ENOBUFS;
+    used = len;
+
+    for (int i = 0; i < shown; i++) {
+        char name[KP_HOOK_NAME_LEN];
+        if (symbol_name_for_addr(info[i].origin_addr, name, sizeof(name))) name[0] = '\0';
+        len = snprintf(out + used, capacity - used,
+                       "\ntype=%s items=%d origin=0x%llx replace=0x%llx name=%s",
+                       hook_type_name(info[i].type), info[i].items,
+                       (unsigned long long)info[i].origin_addr,
+                       (unsigned long long)info[i].replace_addr, name);
+        if (len < 0) return -EINVAL;
+        if (len >= capacity - used) return -ENOBUFS;
+        used += len;
+    }
+    return used;
+}
